import test from 'node:test';
import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
import {Game} from '../dist/engine.js';
import {RunStore,captureRun,restoreRun} from '../dist/run-save.js';

// Generated by the unchanged v11 Game + RunStore at main 08b1c3f6,
// not by relabelling a current snapshot. Contains prior victory history,
// a paused ongoing run, active speech, a trophy and already credited totals.
const raw=readFileSync(new URL('./fixtures/runstore-v11.json',import.meta.url),'utf8');
const memory=value=>{const data=new Map([['toma-popescu-run-v1',value]]);return{getItem:key=>data.get(key)??null,setItem:(key,value)=>data.set(key,value)};};

test('real v11 record reads without mutation and resumes with history and trophies intact',()=>{
 const original=JSON.parse(raw),storage=memory(raw),store=new RunStore(storage),currentVersion=captureRun(new Game()).version;
 assert.equal(original.version,11);assert.equal(original.run.snapshot.version,11);
 assert.equal(original.run.snapshot.game.speech.scene,undefined);
 const read=store.read();assert.equal(read.status,'ready');
 assert.equal(read.value.version,currentVersion);assert.equal(read.value.run.snapshot.version,currentVersion);
 assert.equal(storage.getItem(store.key),raw,'read-only migration does not rewrite original bytes');
 assert.deepEqual(read.value.totals,original.totals);assert.deepEqual(read.value.replay,original.replay);
 const game=restoreRun(read.value.run.snapshot);
 assert.equal(game.s.mode,'paused');assert.equal(game.s.elapsed,123);assert.equal(game.s.hp,67);
 assert.equal(game.s.kills,17);assert.equal(game.s.coins,9);assert.equal(game.rank('muscle'),2);
 assert.equal(game.s.trophies.chosen.travestia,'star');assert.equal(game.speech.active.text,original.run.snapshot.game.speech.active.text);
 assert.equal(game.speech.scene,null);game.resume();assert.equal(game.s.mode,'playing');
 game.s.elapsed++;game.s.kills+=2;game.s.coins++;game.pause();
 assert.equal(store.checkpoint('real-v11-run',game,{credit:true}).ok,true);
 const saved=JSON.parse(storage.getItem(store.key));assert.equal(saved.version,currentVersion);assert.equal(saved.run.snapshot.version,currentVersion);
 assert.deepEqual(saved.totals,{best:1200,lifetime:99,coins:42});assert.equal(saved.revision,original.revision+1);
 assert.equal(saved.replay.history[0].id,'v11-previous-victory');
 assert.equal(store.checkpoint('real-v11-run',game,{credit:true}).ok,true);
 assert.deepEqual(store.read().value.totals,saved.totals,'repeated credit after migration is idempotent');
});

test('record migration rejects invalid envelope versions without rewriting bytes',()=>{
 const currentVersion=captureRun(new Game()).version;
 for(const version of [0,-1,1.5,'11',null,currentVersion+1]){
  const value=JSON.parse(raw);value.version=version;const encoded=JSON.stringify(value),storage=memory(encoded),store=new RunStore(storage);
  assert.equal(store.read().status,'corrupt',`invalid version ${String(version)}`);assert.equal(storage.getItem(store.key),encoded);
 }
});

test('accepting a v11 envelope does not bypass validation of corrupt run contents',()=>{
 for(const change of [value=>value.run.snapshot.game.s.hp=null,value=>value.run.snapshot.version=999,value=>value.replay.history[0].time=-1]){
  const value=JSON.parse(raw);change(value);assert.equal(new RunStore(memory(JSON.stringify(value))).read().status,'corrupt');
 }
});
